'use client'

import {
  cn,
  DismissableLayer,
  focusElement,
  getLinkComponent,
  Presence,
  useAnchorPosition,
  useRovingFocus,
  useSignal,
  useSignals,
} from '@cascivo/core'
import type { RovingOrientation } from '@cascivo/core'
import { useId, useRef } from 'react'
import type { CSSProperties, KeyboardEvent, ReactNode } from 'react'
import styles from './navigation-menu.module.css'

export interface NavigationMenuItem {
  id: string
  label: ReactNode
  href?: string
  content?: ReactNode
}

export interface NavigationMenuProps {
  items: NavigationMenuItem[]
  /**
   * Invisible accessible name. The catalog convention (see the item-identity table in
   * `docs/AI-RULES.md`); `aria-label` is accepted as an alias for the DOM spelling.
   */
  ariaLabel?: string
  /**
   * Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered.
   *
   * `ariaLabel` is the catalog convention and stays preferred, but `label` is the guess an
   * adopter makes when they have not read the convention, and an unaccepted guess costs a
   * compile cycle for nothing (2026-08-21 report item 1). Pass either.
   */
  label?: string
  'aria-label'?: string
  /**
   * Which arrow keys move focus, and the axis the items lay out on: `horizontal`
   * (Left/Right), `vertical` (Up/Down), or `both` (all four).
   *
   * @defaultValue `horizontal`
   * @see the component manifest
   */
  orientation?: RovingOrientation
  className?: string
}

export function NavigationMenu({
  items,
  'aria-label': ariaLabelDom,
  ariaLabel,
  label,
  orientation = 'horizontal',
  className,
}: NavigationMenuProps) {
  useSignals()
  const baseId = useId()
  const openId = useSignal<string | null>(null)
  const roving = useRovingFocus({ orientation, loop: true })

  return (
    <nav
      aria-label={ariaLabel ?? ariaLabelDom ?? label}
      className={cn(styles['nav'], className)}
      data-orientation={orientation}
    >
      <ul role="list" className={styles['list']}>
        {items.map((item, index) => (
          <NavigationMenuEntry
            key={item.id}
            item={item}
            baseId={baseId}
            openId={openId}
            itemProps={roving.getItemProps(index)}
          />
        ))}
      </ul>
    </nav>
  )
}

interface NavigationMenuEntryProps {
  item: NavigationMenuItem
  baseId: string
  openId: ReturnType<typeof useSignal<string | null>>
  itemProps: ReturnType<ReturnType<typeof useRovingFocus>['getItemProps']>
}

function NavigationMenuEntry({ item, baseId, openId, itemProps }: NavigationMenuEntryProps) {
  useSignals()
  const triggerRef = useRef<HTMLButtonElement>(null)
  const floatingRef = useRef<HTMLDivElement>(null)
  const hasContent = item.content != null
  const isOpen = openId.value === item.id
  const panelId = `${baseId}-panel-${item.id}`

  const { anchorStyle, floatingStyle } = useAnchorPosition({
    anchorRef: triggerRef,
    floatingRef,
    placement: 'bottom-start',
    enabled: isOpen,
  })

  const { ref: rovingRef, onKeyDown: rovingKeyDown, ...rovingRest } = itemProps

  if (!hasContent) {
    // A registered link component must forward `ref` to its underlying anchor so
    // roving focus can move to it (TanStack/Next Link both do); defaults to `<a>`.
    const LinkComponent = getLinkComponent()
    return (
      <li className={styles['item']}>
        <LinkComponent
          ref={(el: HTMLAnchorElement | null) => rovingRef(el)}
          href={item.href}
          className={styles['link']}
          onKeyDown={rovingKeyDown}
          {...rovingRest}
        >
          {item.label}
        </LinkComponent>
      </li>
    )
  }

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>): void => {
    rovingKeyDown(event)
    if (event.defaultPrevented) return
    if (event.key === 'Escape') {
      openId.value = null
    }
  }

  return (
    <li className={styles['item']}>
      <button
        ref={(el) => {
          triggerRef.current = el
          rovingRef(el)
        }}
        type="button"
        aria-expanded={isOpen}
        aria-controls={panelId}
        data-state={isOpen ? 'open' : 'closed'}
        className={styles['trigger']}
        style={anchorStyle}
        onClick={() => {
          openId.value = isOpen ? null : item.id
        }}
        onKeyDown={handleKeyDown}
        {...rovingRest}
      >
        {item.label}
      </button>
      <Presence present={isOpen}>
        <NavigationMenuPanel
          panelId={panelId}
          floatingRef={floatingRef}
          floatingStyle={floatingStyle}
          onClose={() => {
            openId.value = null
            focusElement(triggerRef.current)
          }}
        >
          {item.content}
        </NavigationMenuPanel>
      </Presence>
    </li>
  )
}

interface NavigationMenuPanelProps {
  panelId: string
  floatingRef: React.RefObject<HTMLDivElement | null>
  floatingStyle: CSSProperties
  onClose: () => void
  children: ReactNode
}

function NavigationMenuPanel({
  panelId,
  floatingRef,
  floatingStyle,
  onClose,
  children,
}: NavigationMenuPanelProps) {
  return (
    <DismissableLayer onDismiss={onClose}>
      <div ref={floatingRef} id={panelId} className={styles['panel']} style={floatingStyle}>
        {children}
      </div>
    </DismissableLayer>
  )
}

@layer cascivo.component {
  .nav {
    display: inline-flex;
  }

  .list {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .nav[data-orientation='vertical'] .list {
    flex-direction: column;
    align-items: stretch;
  }

  .item {
    position: relative;
  }

  .link,
  .trigger {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    padding-block: var(--cascivo-space-2);
    padding-inline: var(--cascivo-space-3);
    background: transparent;
    border: none;
    border-radius: var(--cascivo-radius-item);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    text-decoration: none;
    cursor: pointer;

    &:hover,
    &[data-state='open'] {
      background: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: var(--cascivo-focus-ring);
      outline-offset: 2px;
    }
  }

  .panel {
    position: fixed;
    inset: auto;
    margin: 0;
    padding: var(--cascivo-space-3);
    min-width: 12rem;
    background: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-overlay);
    box-shadow: var(--cascivo-shadow-md);

    opacity: 1;
    translate: 0 0;
    transition:
      opacity var(--cascivo-motion-enter),
      translate var(--cascivo-motion-enter);

    @starting-style {
      opacity: 0;
      translate: 0 calc(-1 * var(--cascivo-space-2));
    }

    &[data-state='closed'] {
      opacity: 0;
      translate: 0 calc(-1 * var(--cascivo-space-2));
      transition:
        opacity var(--cascivo-motion-exit),
        translate var(--cascivo-motion-exit);
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .panel {
    transition: none;
  }
}

@media (forced-colors: active) {
  .link:focus-visible,
  .trigger:focus-visible {
    outline: 2px solid Highlight;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'NavigationMenu',
  description: 'Site navigation bar with links and dropdown flyout panels',
  category: 'navigation',
  // Top-level items are real anchors so the site stays navigable; only the flyout panels need
  // JS.
  clientJs: 'enhancement',
  states: ['closed', 'open'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'label',
      nameVisibility: 'invisible',
      description:
        'Alias of `ariaLabel` — the same invisible accessible name under the other spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      type: 'string',
      required: false,
      description:
        'Invisible accessible name. The catalog convention; `aria-label` is accepted as an alias for the DOM spelling.',
    },
    {
      name: 'items',
      description: 'The items to render.',
      type: 'NavigationMenuItem[]',
      required: true,
    },
    {
      name: 'aria-label',
      description: 'Accessible label used when no visible label is present.',
      type: 'string',
      required: false,
    },
    {
      name: 'orientation',
      default: 'horizontal',
      description:
        'Which arrow keys move focus, and the axis the items lay out on: `horizontal` (Left/Right), `vertical` (Up/Down), or `both` (all four).',
      type: "'horizontal' | 'vertical' | 'both'",
      required: false,
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-bg-subtle',
    '--cascivo-color-text',
    '--cascivo-color-border',
    '--cascivo-focus-ring',
    '--cascivo-motion-enter',
    '--cascivo-motion-exit',
  ],
  accessibility: {
    role: 'navigation',
    wcag: '2.2-AA',
    // `Space` was missing: the triggers are native `<button>`s, so the browser has always
    // activated them on Space — the manifest simply never said so, and the generated
    // keyboard docs were incomplete because of it.
    keyboard: ['ArrowLeft', 'ArrowRight', 'Home', 'End', 'Enter', 'Space', 'Escape'],
    apgPattern: 'disclosure-navigation',
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    {
      title: 'Basic',
      code: '<NavigationMenu aria-label="Main" items={[{ id: "home", label: "Home", href: "/" }, { id: "products", label: "Products", content: <ul>…</ul> }]} />',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['navigation', 'menu', 'flyout', 'site-nav'],
  intent: {
    whenToUse: [
      'Primary site navigation where some destinations are plain links and others reveal a flyout of grouped links',
      'A header nav bar that mixes direct links with rich dropdown panels',
    ],
    whenNotToUse: [
      'Application commands and actions grouped under File/Edit/View — use Menubar',
      'A single trigger opening a list of actions — use a Menu/Dropdown',
      'Switching between peer content panels in place — use Tabs',
    ],
    antiPatterns: [
      {
        bad: 'Putting action commands (Save, Delete) inside NavigationMenu flyouts',
        good: '<Menubar> or <Menu> for commands; NavigationMenu is for destinations',
        why: 'navigation landmark implies moving between destinations, not invoking actions',
      },
    ],
    related: [
      {
        name: 'Menubar',
        relationship: 'alternative',
        reason: 'Menubar invokes application commands; NavigationMenu navigates to destinations',
      },
      {
        name: 'Tabs',
        relationship: 'alternative',
        reason: 'Tabs swap in-page panels; NavigationMenu links to other destinations',
      },
    ],
    a11yRationale:
      'Wrapped in a navigation landmark with a roving-tabindex row of links and disclosure triggers; triggers expose aria-expanded/aria-controls onto a flyout panel, and outside-pointer or Escape dismisses the open panel and restores trigger focus',
    flexibility: [
      {
        area: 'orientation',
        level: 'flexible',
        note: 'horizontal (default) or vertical roving navigation',
      },
      {
        area: 'panel content',
        level: 'flexible',
        note: 'content is arbitrary ReactNode; links without content render as plain anchors',
      },
    ],
  },
}
